(()=>{
const theme=document.body.dataset.concept;
if(theme==='azulejo'){const track=document.querySelector('.horizontal-rooms');const bar=document.createElement('div');bar.className='room-track-controls';bar.innerHTML='<button aria-label="Previous room">←</button><button aria-label="Next room">→</button>';track.after(bar);bar.children[0].onclick=()=>track.scrollBy({left:-track.clientWidth*.75,behavior:reduced?'instant':'smooth'});bar.children[1].onclick=()=>track.scrollBy({left:track.clientWidth*.75,behavior:reduced?'instant':'smooth'});}
if(theme==='postcard'){const track=document.querySelector('.room-grid');track.classList.add('room-deck');const cards=Array.from(track.querySelectorAll('.room'));let index=0;const bar=document.createElement('div');bar.className='deck-controls';bar.innerHTML='<button aria-label="Previous room postcard">←</button><span aria-live="polite"></span><button aria-label="Next room postcard">→</button>';track.after(bar);function render(){cards.forEach((c,i)=>{c.hidden=i!==index;c.classList.add('visible')});bar.querySelector('span').textContent=`${index+1} / ${cards.length} · ${cards[index].querySelector('h3').textContent}`;}bar.children[0].onclick=()=>{index=(index+cards.length-1)%cards.length;render()};bar.children[2].onclick=()=>{index=(index+1)%cards.length;render()};document.querySelector('.room-filters').hidden=true;render();}
if(theme==='nocturne'){document.querySelectorAll('.room').forEach((room,i)=>{const details=document.createElement('details');details.className='museum-room';details.open=i===0;const summary=document.createElement('summary');summary.innerHTML=`<span>0${i+1} / THE ROOMS</span>${room.querySelector('h3').textContent}`;const content=document.createElement('div');while(room.firstChild)content.append(room.firstChild);details.append(summary,content);room.replaceWith(details);});document.querySelector('.room-filters').hidden=true;}
if(theme==='atlas'){const a=document.querySelector('#quick-arrival'),b=document.querySelector('#quick-departure');a.min=dateString(new Date());b.min=tomorrow(a.min);a.addEventListener('change',()=>{b.min=tomorrow(a.value||a.min);if(b.value&&b.value<b.min)b.value=''});document.querySelector('#quick-plan').addEventListener('click',()=>{openEnquiry();if(a.value)form.elements.arrival.value=a.value;if(b.value)form.elements.departure.value=b.value;form.elements.departure.min=tomorrow(form.elements.arrival.value||dateString(new Date()));});}
if(theme==='folio'){let index=0;const labels=['THE HERITAGE LOUNGE','AFTERNOONS BY THE POOL','YOUR HERITAGE SUITE'],slides=document.querySelectorAll('.folio-slide'),thumbs=document.querySelectorAll('[data-pick-slide]');function show(n){index=(n+slides.length)%slides.length;slides.forEach((s,i)=>s.classList.toggle('is-active',i===index));thumbs.forEach((b,i)=>b.classList.toggle('is-active',i===index));document.querySelector('#folio-caption').textContent=`0${index+1} / ${labels[index]}`;}document.querySelector('[data-slide-prev]').onclick=()=>show(index-1);document.querySelector('[data-slide-next]').onclick=()=>show(index+1);thumbs.forEach(b=>b.onclick=()=>show(Number(b.dataset.pickSlide)));}
if(theme==='courtyard'){const chapters={rest:['bed','A room with soul.','Carved wood, traditional details and space to settle in.','#rooms','Explore the rooms ↗'],pause:['gardenview','Nothing on the agenda.','A garden pool, a quiet corner, and an afternoon that belongs to you.','#moments','Explore the property ↗'],wander:['furniture','Anjuna outside.','Head to the beach, browse the market, and return to a heritage home.','#neighbourhood','Explore Anjuna ↗']};document.querySelectorAll('[data-chapter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-chapter]').forEach(x=>x.classList.toggle('active',x===b));const c=chapters[b.dataset.chapter],panel=document.querySelector('#chapter-panel');panel.querySelector('img').src=`../assets/${c[0]}-enhanced.jpg`;panel.querySelector('img').alt=c[1];panel.querySelector('h2').textContent=c[1];panel.querySelector('p').textContent=c[2];panel.querySelector('a').href=c[3];panel.querySelector('a').textContent=c[4];}));}
})();
